best, best_n = -1, 0
memo = {1: 0}

def F(n):
    path = []
    while n not in memo:
        path.append(n)
        n = n // 2 if n % 2 == 0 else 3 * n + 1
    v = memo[n]
    for m in reversed(path):
        v += 1
        memo[m] = v
    return memo[path[0]] if path else v

for n in range(1, 100001):
    v = F(n)
    if v > best:
        best, best_n = v, n
print(best_n)
